// ===== Classify Customer Intent V9.1: Menu + Website + Herbs + Custom Order + Rage Filter + GUARD + ORDER-ID ANYWHERE + EXISTING-ORDER REF + MENU DEMAND PHRASES =====
function distance(a,b) {
  if (Math.abs(a.length-b.length)>2) return 3;
  let prior=Array.from({length:b.length+1},(_,i)=>i);
  for(let i=1;i<=a.length;i++) {
    const next=[i];
    for(let j=1;j<=b.length;j++) next[j]=Math.min(next[j-1]+1,prior[j]+1,prior[j-1]+(a[i-1]===b[j-1]?0:1));
    prior=next;
  }
  return prior[b.length];
}
function aliases(row) {
  const raw=row.aliases || row.search_aliases || '';
  let list=raw;
  if(typeof raw==='string') {
    try { list=JSON.parse(raw); } catch { list=raw.split(','); }
  }
  return [row.name,...(Array.isArray(list)?list:[])].filter(Boolean).map(normalize);
}
function findProduct(query,rows) {
  if(!query || query.length<3) return null;
  const matches=[];
  for(const row of rows) for(const alias of aliases(row)) {
    if(!alias || alias.length<3) continue;
    const exact=query===alias || (` ${query} `).includes(` ${alias} `);
    const words=query.split(' ');
    const fuzzy=alias.length>=5 && words.some(word=>word.length>=4 && Math.abs(word.length-alias.length)<=2 && distance(word,alias)<= (alias.length>=7?2:1));
    if(exact||fuzzy) matches.push({row,score:exact?100+alias.length:alias.length});
  }
  matches.sort((a,b)=>b.score-a.score);
  if(!matches.length || (matches[1] && matches[0].score===matches[1].score && matches[0].row.name!==matches[1].row.name)) return null;
  return matches[0].row;
}
function normalize(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[\u200B-\u200F\uFEFF]/g, '')
    .replace(/[\u064B-\u065F\u0670\u0640]/g, '')
    .replace(/[أإآ]/g, 'ا')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
function exact(value, list) {
  return list.some(x => value === normalize(x));
}
function has(value, list) {
  const padded = ` ${value} `;
  return list.some(x =>
    padded.includes(` ${normalize(x)} `)
  );
}
function looksLikeQuestion(text, raw) {
  if (/\?|؟/.test(raw || '')) return true;
  return has(text, [
    'kya','kia','kaise','kese','kesa','kaisa','kyun','kyu','kab','kahan','kitna','kitne','kitni',
    'kaun','kon','konsa','faida','fayda','faide','fayde','benefit','benefits','nutrition',
    'price','rate','cost','detail','details','info','jankari','batao','batado',
    'istemal','istamal','istemaal','tarika','tareeka','use','what','how','when','where','why','which',
    'کیا','کیسے','کب','کہاں',
  ]);
}
function safeContext(source) {
  try {
    const value =
      typeof source === 'string'
        ? JSON.parse(source || '{}')
        : (source || {});
    return value &&
      typeof value === 'object' &&
      !Array.isArray(value)
      ? value
      : {};
  } catch {
    return {};
  }
}
function isQuantityChange(raw) {
  const q = String(raw || '').normalize('NFKC').toLowerCase().replace(/,/g, '.').trim();
  return /^(make it |karo |kar do |change |badal |chahiye )?\d+(?:\.\d+)?\s*(g|gm|gram|grams|kg|kgs|kilogram|kilograms|box|boxes|pack|packs|packet|packets|piece|pieces|pc|pcs)?\s*(chahiye|hai)?$/.test(q);
}
function extractQuantity(raw) {
  const m = String(raw || '').normalize('NFKC').toLowerCase().replace(/,/g, '.').match(/(\d+(?:\.\d+)?)\s*(g|gm|gram|grams|kg|kgs|kilogram|kilograms|box|boxes|pack|packs|packet|packets|piece|pieces|pc|pcs)?\s*$/);
  return m ? (m[1] + (m[2] ? m[2] : '')) : String(raw || '').trim();
}

// ===== RAGE FILTER: abuse vs complaint =====
const ABUSE_WORDS = [
  'fraud','fraudster','chor','loot','lootere','ghatiya','bakwas','bekar','pagal','pagal ho',
  'harami','haraami','bewakoof','ullu','ullu ka patha','third class','3rd class','nalayak',
  'badtameez','jali','scam','scammer','dhoka','cheater','cheat','stupid','idiot','fool',
  'nonsense','rubbish','worst','pathetic','useless','chor hai','loot rahe','loot rahe ho',
];
const COMPLAINT_WORDS = [
  'kharab','damaged','damage','toota','tuti','broken','ghalat','wrong','missing',
  'refund','wapas','return','complain','complaint','shikayat','shikwa','shikvaat',
];

const CHOICES = {
  menu_catalogue: 'browse_products',
  menu_deals: 'deals',
  menu_herbs: 'herbs_spices',
  menu_custom: 'custom_order',
  menu_tracking: 'order_status',
  menu_faq: 'faq_help',
  menu_ai: 'ai_start',
  menu_human: 'human_support',
  menu_website: 'open_website',
  // legacy buttons (purane menu wale customers ke liye)
  menu_dry_fruits: 'browse_products',
  menu_snacks: 'browse_products',
  menu_gift_boxes: 'browse_products',
  confirm_yes: 'confirm_order',
  confirm_no: 'cancel_order',
};
const NUMBERS = {
  '1': 'browse_products',
  '2': 'deals',
  '3': 'herbs_spices',
  '4': 'custom_order',
  '5': 'order_status',
  '6': 'faq_help',
  '7': 'ai_start',
  '8': 'human_support',
  '9': 'open_website',
  '0': 'menu',
};
const MENU_CATEGORIES = {
  menu_dry_fruits: 'Dry Fruits & Nuts',
  menu_snacks: 'Snacks & Seeds',
  menu_gift_boxes: 'Gift Boxes',
};
const TITLE_KEYWORDS = [
  [/catalog/i, 'browse_products', null],
  [/deal|offer/i, 'deals', null],
  [/herbs?\s*&?\s*spices?|herbs|spices|masala/i, 'herbs_spices', null],
  [/custom\s*order|custom|special order/i, 'custom_order', null],
  [/dry fruit/i, 'browse_products', 'Dry Fruits & Nuts'],
  [/snack/i, 'browse_products', 'Snacks & Seeds'],
  [/gift/i, 'browse_products', 'Gift Boxes'],
  [/order/i, 'place_order', null],
  [/track/i, 'order_status', null],
  [/ai health|health bot/i, 'ai_start', null],
  [/faq|help/i, 'faq_help', null],
  [/human|support/i, 'human_support', null],
];
const catalogue = $input.all().map(item => item.json || {}).filter(row => row.active !== false && row.name);
const item = {json: $('Prepare Conversation Context').first().json};
return [(() => {
  const index = 0;
  const data = item.json || {};
  const rawText =
    typeof data.text === 'string'
      ? data.text.trim()
      : String(data.text?.body || '').trim();
  const text = normalize(rawText);
  const rawChoice = String(data.choiceId || '')
    .trim()
    .toLowerCase();
  const command = values =>
    exact(text, values) || exact(rawChoice, values.map(x => normalize(x)));
  let state = String(
    data.sessionState ||
    data.state ||
    'idle'
  ).trim().toLowerCase();
  const expiresAt = Date.parse(data.expires_at || '');
  if (
    data.active === false ||
    data.active === 'false' ||
    (
      Number.isFinite(expiresAt) &&
      expiresAt <= Date.now()
    )
  ) {
    state = 'idle';
  }
  const context = safeContext(
    data.sessionContext ?? data.context_json
  );
  let intent = 'unknown';
  let confidence = 0;
  const duplicate = Boolean(data.last_message_id && data.last_message_id === data.messageId);
  const isText = ['text','button','interactive','reaction'].includes(String(data.messageType || '').toLowerCase());

  // ===== GUARD: opt-out text pehchano — forceMenu inhe khae ga nahi =====
  const isOptOutText = command([
    'cancel', 'cancel order', 'cancel_order', 'order cancel', 'cancel karo', 'cancel kardo', 'cancel krdo', 'کینسل', 'منسوخ',
    'stop', 'stop messages', 'stop reminders', 'reminder band', 'reminders band',
    'band karo', 'band kardo', 'band krdo', 'nahi chahiye', 'nahin chahiye', 'abhi nahi chahiye',
  ]);

  // ===== FIX V8: ORDER ID KAHIN BHI HO — TRACKING PAR BHEJO =====
  // Website format: AB-20261005-63BC11 (2-part hex) + WhatsApp format: AB-20261004-143025-5065 (3-part)
  const orderIdMatch = rawText.trim().match(/(?:^|\s)ab[\s:-]*(20\d{6})[\s:-]*([a-z0-9]{2,10})(?:[\s:-]*(\d{2,6}))?(?![a-z0-9])/i);
  if (orderIdMatch) {
    data.trackingOrderId = ('AB-' + orderIdMatch[1] + '-' + orderIdMatch[2] + (orderIdMatch[3] ? '-' + orderIdMatch[3] : '')).toUpperCase();
  }

  // ===== FIX V9: EXISTING ORDER REFERENCE — customer purane order ki baat kar raha hai =====
  // "jo mene order kia huwa wohi chahiye", "mera order jaldi", "mera parcel" etc.
  const referencesExistingOrder =
    has(text, [
      'mera order', 'meri order', 'mene order', 'maine order', 'wohi order', 'wohi wala',
      'pehle wala', 'pehla wala', 'same order', 'pichla order', 'pichle order',
      'mera parcel', 'mera shipment', 'mera package',
    ]) ||
    /(mene|maine)\s+order\s+(kia|kiya)/i.test(rawText) ||
    /order\s+(kia|kiya)\s+huwa/i.test(rawText);

  // ===== PEHLA MSG = MENU (opt-out + Order ID + purane-order-reference chhod kar) =====
  const forceMenu = (state === 'idle' && !rawChoice && !isOptOutText && !orderIdMatch && !referencesExistingOrder);

  if (orderIdMatch && !isOptOutText && state !== 'human_handoff') {
    intent = 'order_status'; confidence = 1;
  } else if (forceMenu) {
    intent = 'menu'; confidence = 1;
  } else if (duplicate) {
    intent = 'duplicate_message'; confidence = 1;
  } else if (!isText || (!rawText && !rawChoice)) {
    intent = 'unsupported_media'; confidence = 1;
  } else if (
    command([
      'cancel',
      'cancel order',
      'cancel_order',
      'order cancel',
      'cancel karo',
      'cancel kardo',
      'cancel krdo',
      'کینسل',
      'منسوخ',
    ])
  ) {
    intent = 'cancel_order';
    confidence = 1;
  } else if (
    // ===== GUARD: STOP / soft opt-out → cancel_order =====
    // Late cancel (session expire) aur soft mana ("nahi chahiye") dono yahan pakde jate hain.
    state !== 'human_handoff' &&
    (
      command([
        'stop', 'stop messages', 'stop reminders', 'reminder band', 'reminders band',
        'band karo', 'band kardo', 'band krdo', 'disturb nahi karo', 'pareshan na karo',
      ]) ||
      (
        ['awaiting_quantity', 'awaiting_address', 'idle'].includes(state) &&
        rawText.length <= 40 &&
        has(text, [
          'cancel kar do', 'cancel karde', 'cancel karo',
          'nahi chahiye', 'nahin chahiye', 'abhi nahi', 'abhi nahi chahiye',
          'order nahi karna', 'nahi order karna', 'mat bhejo', 'disturb nahi', 'reminder nahi',
          'band karo', 'band kardo', 'band krdo',
        ])
      )
    )
  ) {
    intent = 'cancel_order';
    confidence = 1;
  } else if (String(data.messageType || '').toLowerCase() === 'reaction') {
    // ===== REACTIONS: 👍=Confirm/Menu, ❌/🛑=Cancel =====
    if (rawText.includes('❌') || rawText.includes('🛑')) {
      intent = 'cancel_order'; confidence = 1;
    } else if (rawText.includes('👍') || rawText.includes('✅') || rawText.includes('❤️')) {
      intent = (state === 'awaiting_confirmation') ? 'confirm_order' : 'menu';
      confidence = 1;
    } else {
      intent = 'menu'; confidence = 1;
    }
  } else if (
    /^ab[\s:-]*\d{4,8}[\s:-]*\d{4,6}[\s:-]*\d{2,4}$/i.test(rawText.trim())
  ) {
    // ===== ORDER ID (3-part, pura message = sirf ID) =====
    intent = 'order_status';
    confidence = 1;
    const oidParts = rawText.trim().match(/^ab[\s:-]*(\d{4,8})[\s:-]*(\d{4,6})[\s:-]*(\d{2,4})$/i);
    data.trackingOrderId = 'AB-' + oidParts[1] + '-' + oidParts[2] + '-' + oidParts[3];
  } else if (rawChoice.startsWith('cat_')) {
    const catMap = { cat_dryfruits:'Dry Fruits & Nuts', cat_oils:'Oils', cat_desi:'Desi Essentials',
      cat_snacks:'Snacks & Seeds', cat_gifts:'Gift Boxes', cat_herbs:'Herbs & Spices' };
    intent = 'browse_products'; confidence = 1;
    data.browseCategory = catMap[rawChoice] || '';
  } else if (rawChoice.startsWith('prod_')) {
    const prow = catalogue.find(r => String(r.base_product_id).toLowerCase() === rawChoice.slice(5));
    if (prow) {
      intent = 'order_product'; confidence = 1;
      data.selectedProductId = String(prow.base_product_id);
      data.selectedProduct = prow.name;
    } else {
      intent = 'browse_products'; confidence = 0.9;
    }
  } else if (rawChoice.startsWith('qty_')) {
    const bodyStr = rawChoice.slice(4);
    const cut = bodyStr.lastIndexOf('_');
    const pid = bodyStr.slice(0, cut);
    const tail = bodyStr.slice(cut + 1);
    const prow = catalogue.find(r => String(r.base_product_id).toLowerCase() === pid);
    if (prow) {
      data.selectedProductId = String(prow.base_product_id);
      data.selectedProduct = prow.name;
      if (tail === 'custom') {
        intent = 'order_quantity_custom'; confidence = 1;
        data.customQty = true;
      } else {
        intent = 'order_quantity'; confidence = 1;
        data.quantityChoice = tail;
      }
    } else {
      intent = 'menu'; confidence = 1;
    }
  } else if (rawChoice.startsWith('win_')) {
    // ===== DELIVERY WINDOW BUTTON: win_fastest::AB-... =====
    const parts = rawChoice.slice(4).split('::');
    const wtype = (parts[0] || '').trim();
    const joid = (parts[1] || '').trim();
    const wmap = { fastest: 'Fastest', morning: 'Morning', evening: 'Evening', night: 'Night' };
    if (wmap[wtype] && joid) {
      intent = 'delivery_window'; confidence = 1;
      data.windowChoice = wmap[wtype];
      data.journeyOrderId = joid;
    } else {
      intent = 'menu'; confidence = 1;
    }
  } else if (rawChoice.startsWith('fb_')) {
    // ===== FEEDBACK BUTTON: fb_great::AB-... =====
    const parts = rawChoice.slice(3).split('::');
    const ftype = (parts[0] || '').trim();
    const joid = (parts[1] || '').trim();
    const fmap = { great: 'great', good: 'good', ok: 'ok', bad: 'bad' };
    if (fmap[ftype] && joid) {
      intent = 'feedback'; confidence = 1;
      data.feedbackRating = ftype;
      data.journeyOrderId = joid;
    } else {
      intent = 'menu'; confidence = 1;
    }
  } else if (CHOICES[rawChoice]) {
    intent = CHOICES[rawChoice];
    confidence = 1;
    if (MENU_CATEGORIES[rawChoice]) {
      data.browseCategory = MENU_CATEGORIES[rawChoice];
    }
  } else if (rawChoice) {
    const numMatch = rawChoice.match(/^(\d+)\s*[\.\)]?\s*/);
    const numKey = numMatch ? numMatch[1] : '';
    if (numKey && NUMBERS[numKey]) {
      intent = NUMBERS[numKey];
      confidence = 1;
      if (MENU_CATEGORIES[numKey]) {
        data.browseCategory = MENU_CATEGORIES[numKey];
      }
    } else {
      const kw = TITLE_KEYWORDS.find(([re]) => re.test(rawChoice));
      if (kw) {
        intent = kw[1];
        confidence = 1;
        if (kw[2]) data.browseCategory = kw[2];
      } else {
        intent = 'menu'; confidence = 0.8;
      }
    }
  } else if (
    command([
      'website',
      'web',
      'site',
      'allbarka com',
      'allbarka dot com',
    ]) ||
    has(text, ['website', 'allbarka com'])
  ) {
    // ===== V9: WEBSITE — allbarka.com ("9. Website" quote-reply bhi yahan pakda jata hai) =====
    intent = 'open_website';
    confidence = 1;
  } else if (
    command([
      'menu',
      'main menu',
      'home',
      'start',
      'hi',
      'hello',
      'hey',
      'salam',
      'assalamualaikum',
      'اسلام علیکم',
      'السلام عليكم',
    ]) ||
    has(text, [
      // ===== V9.1: MENU DEMAND PHRASES — "menu do" jaise demands direct interactive menu par =====
      'menu do', 'menu dikhao', 'menu dikha do', 'menu dikhade', 'menu chahiye', 'menu lao',
      'menu kholo', 'menu open karo', 'menu bhejo', 'menu dekhao', 'menu dekhna', 'menu show karo',
      'menu par jao', 'menu par le jao', 'menu wapis', 'wapis menu', 'main menu do',
      'options dikhao', 'options chahiye', 'options do', 'menu list do',
    ])
  ) {
    intent = 'menu';
    confidence = 1;
  } else if (
    command([
      'human',
      'human support',
      'support',
      'agent',
      'representative',
      'customer support',
      'talk to human',
      'human se baat',
    ])
  ) {
    intent = 'human_support';
    confidence = 1;
  } else if (
    command([
      'tracking',
      'track',
      'order status',
      'track order',
      'track my order',
      'where is my order',
      'order kahan hai',
    ])
  ) {
    intent = 'order_status';
    confidence = 1;
  } else if (
    command([
      'order',
      'new order',
      'place order',
      'place_order',
      'buy',
      'order karna hai',
    ])
  ) {
    intent = 'place_order';
    confidence = 1;
  } else if (
    command(['ai', 'ai bot', 'health bot', 'ai health bot', 'health', 'sehat'])
  ) {
    intent = 'ai_start';
    confidence = 1;
  } else if (
    // ===== RAGE FILTER: abuse → direct human (quiet mode mein nahi) =====
    has(text, ABUSE_WORDS) && state !== 'human_handoff'
  ) {
    intent = 'human_support'; confidence = 1;
    data.rageFlag = true;
  } else if (
    // ===== COMPLAINT: AI details collect karega =====
    has(text, COMPLAINT_WORDS) && state !== 'human_handoff' && state !== 'awaiting_custom_order'
  ) {
    intent = 'faq'; confidence = 1;
    data.complaintFlag = true;
  } else if (state === 'ai_chat') {
    intent = 'faq';
    confidence = 0.95;
  } else if (state === 'human_handoff') {
    // ===== BOT QUIET MODE: free-text SILENT drop =====
    intent = 'duplicate_message';
    confidence = 1;
  } else if (state === 'awaiting_custom_order') {
    // ===== CUSTOM ORDER: customer apni desired product likh raha hai =====
    if (rawText.length >= 3) {
      intent = 'custom_order_details'; confidence = 1;
    } else {
      intent = 'custom_order_details'; confidence = 0.7;
    }
  } else if (
    has(text, [
      'products',
      'product',
      'catalogue',
      'catalog',
      'items',
      'saman',
      'saaman',
      'price list',
      'kya bikta',
      'kya milta',
    ]) &&
    !has(text, ['order','buy','purchase','khareedna','kharidna'])
  ) {
    intent = 'browse_products';
    confidence = 0.9;
  } else if (
    looksLikeQuestion(text, rawText) &&
    !has(text, ['order','buy','purchase','khareedna','kharidna'])
  ) {
    intent = 'faq';
    confidence = 0.9;
  } else if (has(text,['order','buy','purchase','khareedna','kharidna']) && findProduct(text,catalogue)) {
    intent = 'order_product'; confidence = 0.94;
  } else if (state === 'awaiting_confirmation') {
    if (
      command([
        'yes',
        'confirm',
        'ok',
        'okay',
        'haan',
        'han',
        'ji',
        'jee',
        '1',
      ])
    ) {
      intent = 'confirm_order';
      confidence = 1;
    } else if (
      command([
        'no',
        'nahi',
        'nahin',
        '2',
      ])
    ) {
      intent = 'cancel_order';
      confidence = 1;
    } else if (isQuantityChange(rawText) && (context.product || data.selectedProduct)) {
      // ===== MID-ORDER QUANTITY CHANGE =====
      intent = 'order_quantity';
      confidence = 1;
      data.quantityChoice = extractQuantity(rawText);
    } else {
      intent = 'order_confirmation';
      confidence = 0.95;
    }
  } else if (state === 'awaiting_product') {
    if (referencesExistingOrder) {
      // ===== V9: order ke darmiyan purane order ka zikr → AI par chhor do =====
      intent = 'faq';
      confidence = 0.9;
    } else if (rawText.length <= 80 && findProduct(text, catalogue)) {
      intent = 'order_product';
      confidence = 0.95;
    } else if (looksLikeQuestion(text, rawText)) {
      intent = 'faq';
      confidence = 0.9;
    } else {
      intent = 'order_product_invalid';
      confidence = 1;
    }
  } else if (state === 'awaiting_quantity') {
    const quantityText = rawText
      .normalize('NFKC')
      .toLowerCase()
      .replace(/,/g, '.')
      .replace(/\s+/g, ' ')
      .trim();
    const quantityMatch = quantityText.match(
      /^(\d+(?:\.\d+)?)\s*(g|gm|gram|grams|kg|kgs|kilogram|kilograms|box|boxes|pack|packs|packet|packets|piece|pieces|pc|pcs)?$/
    );
    const amount = quantityMatch
      ? Number(quantityMatch[1])
      : NaN;
    if (
      quantityMatch &&
      Number.isFinite(amount) &&
      amount > 0 &&
      amount <= 10000
    ) {
      intent = 'order_quantity';
      confidence = 1;
    } else if (looksLikeQuestion(text, rawText)) {
      intent = 'faq';
      confidence = 0.9;
    } else {
      intent = 'order_quantity_invalid';
      confidence = 1;
    }
  } else if (state === 'awaiting_address') {
    if (isQuantityChange(rawText) && (context.product || data.selectedProduct)) {
      intent = 'order_quantity';
      confidence = 1;
      data.quantityChoice = extractQuantity(rawText);
    } else if (
      rawText.length >= 12 &&
      rawText.length <= 300 &&
      rawText.includes(' ')
    ) {
      intent = 'order_address';
      confidence = 0.95;
    } else {
      intent = 'order_address_invalid';
      confidence = 1;
    }
  } else if (state === 'awaiting_delivery_window') {
    // ===== DELIVERY WINDOW: text reply (button ya text dono) =====
    let wc = '';
    if (has(text, ['fastest', 'jaldi', 'turant', 'foran', 'fast'])) wc = 'Fastest';
    else if (has(text, ['morning', 'subah', 'saveray', 'savere'])) wc = 'Morning';
    else if (has(text, ['evening', 'sham', 'shaam'])) wc = 'Evening';
    else if (has(text, ['night', 'raat', 'rat'])) wc = 'Night';
    if (wc) {
      intent = 'delivery_window'; confidence = 1;
      data.windowChoice = wc;
      data.journeyOrderId = context.order_id || data.journeyOrderId || '';
    } else if (looksLikeQuestion(text, rawText)) {
