    confidence = 0.9;
  } else if (
    referencesExistingOrder &&
    has(text, ['cancel', 'band karo', 'khatam'])
  ) {
    intent = 'cancel_order';
    confidence = 1;
  } else if (referencesExistingOrder) {
    // "jo mene order kia huwa wohi chahiye jaldi" → AI (order context ke sath) decide karega
    intent = 'faq';
    confidence = 0.9;
  } else if (
    has(text, ['order']) &&
    has(text, ['kahan','kab','status','track','aayega','hua'])
  ) {
    intent = 'order_status';
    confidence = 0.9;
  } else if (findProduct(text, catalogue)) {
    intent = 'order_product';
    confidence = 0.94;
  } else if (
    has(text, [
      'dry fruit',
      'dry fruits',
      'kishmish',
      'khajoor',
    ])
  ) {
    intent = 'browse_products';
    confidence = 0.9;
    data.browseCategory = 'Dry Fruits & Nuts';
  } else if (
    has(text, [
      'snack',
      'snacks',
      'chips',
    ])
  ) {
    intent = 'browse_products';
    confidence = 0.9;
    data.browseCategory = 'Snacks & Seeds';
  } else if (
    has(text, [
      'gift',
      'gift box',
      'gift boxes',
    ])
  ) {
    intent = 'browse_products';
    confidence = 0.9;
    data.browseCategory = 'Gift Boxes';
  } else if (
    has(text, [
      'delivery',
      'shipping',
      'payment',
      'cod',
      'return',
      'refund',
      'delivery charges',
      'faq',
      'help',
    ])
