      'order',
      'buy',
      'purchase',
      'khareedna',
      'kharidna',
    ])
  ) {
    intent = 'place_order';
    confidence = 0.85;
  } else {
    intent = 'faq';
    confidence = 0.5;
  }
  let detectedLanguage = 'en';
  if (/[\u0600-\u06FF]/.test(rawText)) {
