    || (rawText.length > 180 && rawText.includes('\n'));
  if (intent === 'order_product' && !data.selectedProductId && (!selectedProduct || looksLikeConfirmation)) {
    intent = looksLikeConfirmation ? 'order_status' : 'order_product_invalid';
