function normalize(value) {
  return String(value ?? '')
    .normalize('NFKC')
    .toLowerCase()
    .replace(/[\u200B-\u200F\uFEFF]/g, '')
    .replace(/[^a-z0-9\u0600-\u06FF\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function safeContext(value) {
  try {
    const parsed =
      typeof value === 'string'
        ? JSON.parse(value || '{}')
        : (value || {});

    return parsed &&
      typeof parsed === 'object' &&
      !Array.isArray(parsed)
      ? parsed
      : {};
  } catch {
    return {};
  }
}

function profitableRound(value) {
  const amount = Math.ceil(Number(value));

  // Custom price ko aglay profitable 9 par round karega.
  return Math.ceil((amount + 1) / 10) * 10 - 1;
}

function formatMoney(value) {
  return Number(value).toLocaleString('en-PK');
}

function formatWeight(weightG) {
  if (weightG >= 1000) {
    const kg = Number((weightG / 1000).toFixed(3));
    return `${kg}kg`;
  }

  return `${weightG}g`;
}

function aliases(row) {
  let raw=row.aliases || row.search_aliases || '';
  if(typeof raw==='string') { try {raw=JSON.parse(raw)} catch {raw=raw.split(',')} }
  return [row.name,...(Array.isArray(raw)?raw:[])].filter(Boolean).map(normalize);
}

