    st.startsWith('PREPAR') ||
    st.startsWith('DISP') ||
    st.startsWith('OUT') ||
    st.startsWith('DELIV');
  return d.getMonth() === now.getMonth() &&
    d.getFullYear() === now.getFullYear() &&
