  'pack',
  'packs',
  'packet',
  'packets',
  'piece',
  'pieces',
  'pc',
  'pcs',
];

if (gramUnits.includes(unit)) {
  weightG = amount;
} else if (kilogramUnits.includes(unit)) {
  weightG = amount * 1000;
} else if (packUnits.includes(unit)) {
  if (!Number.isInteger(amount)) {
    weightG = 0;
  } else {
    packCount = amount;
    weightG = amount * 1000;
  }
} else {
