// Status code → friendly label (CONF, DELIV, PEND, PROC, DISP, CANC...)
const statusMap = {
  RECEIVED: 'Order Received 📥',
  CONF: 'Confirmed ✅',
  ORDER: 'Order Received 📥',
  PROC: 'Processing ⏳',
  PACK: 'Packed 📦',
  DISP: 'Dispatched 🚚',
  SHIP: 'Shipped 🚚',
  DELIV: 'Delivered ✅',
  PEND: 'Pending ⏳',
  CANC: 'Cancelled ❌',
  RTN: 'Returned ↩️',
};
const friendly = s => {
  const t = String(s || '').toUpperCase().trim();
  const hit = Object.keys(statusMap).find(k => t.startsWith(k));
  return hit ? statusMap[hit] : (s || 'Unknown');
};

// Product/quantity — dono schemas support (wa_orders: product/quantity, Order_Control: items_summary)
const productName = r => {
  const p = String(r.product || r.items_summary || '-');
  return p.replace(/\s*\([^)]*\)\s*$/, '').trim() || '-';
};
const quantityOf = r => {
  if (r.quantity) return String(r.quantity);
  const m = String(r.items_summary || r.product || '').match(/\(([^)]+)\)/);
  return m ? m[1] : '-';
};

// Multiple orders ho to LATEST pick karo (order_date ke mutabiq)
let row = null;
if (rows.length === 1) {
  row = rows[0];
} else if (rows.length > 1) {
  const ts = r => {
    const d = Date.parse(String(r.order_date || '').replace(' ', 'T'));
    return isNaN(d) ? 0 : d;
  };
  row = [...rows].sort((a, b) => ts(b) - ts(a))[0];
}

let replyText;
if (row) {
  const dateLine = row.order_date
    ? '📅 Date: ' + String(row.order_date).slice(0, 16) + '\n'
    : '';
  replyText =
    '📦 *Order Status*\n\n' +
    '🧾 Order ID: *' + row.order_id + '*\n' +
    '🛍️ Product: *' + productName(row) + '*\n' +
    '⚖️ Quantity: *' + quantityOf(row) + '*\n' +
    (row.total_amount ? '💰 Total: *Rs ' + Number(row.total_amount).toLocaleString('en-PK') + '*\n' : '') +
    dateLine +
    '📦 Status: *' + friendly(row.status) + '*\n\n' +
    'Menu ke liye *Menu* likhein.';
} else if (classify.trackingOrderId) {
  replyText =
    '❌ Is Order ID se koi order nahi mila.\n\n' +
    'Order ID dobara check karein: *AB-YYYYMMDD-HHMMSS-XXXX*\n\n' +
    'Apne number ke latest order ke liye *Tracking* likhein.';
} else {
  replyText = 'Aapke number par koi order nahi mila. Naya order dene ke liye *Order* likhein.\n\nMenu ke liye *Menu* likhein.';
}

return [{ json: { ...ctx, to: ctx.from, replyType: 'order_tracking', replyText } }];

// ===== Build AI Payload V2 (Groq) — Customer Care + Sales + Orders + Flow State + History =====
const ctx = $('Prepare Conversation Context').first().json || {};
const q = String(ctx.text || '').trim() || 'salam';
const state = String(ctx.sessionState || 'idle');

let sessCtx = {};
try { sessCtx = JSON.parse(ctx.sessionContext || '{}') || {}; } catch (e) { sessCtx = {}; }

// ===== VERIFIED ORDERS (customer ke asli orders) =====
const orders = $('Load AI Orders').all().map(i => i.json || {}).filter(o => o && o.order_id);
const statusMap = {
  RECEIVED: 'order mil gaya hai', ORDER: 'order mil gaya hai', CONF: 'confirm ho gaya hai',
  PROC: 'process mein hai', PACK: 'pack ho gaya hai', DISP: 'dispatch ho gaya hai',
  SHIP: 'ship ho gaya hai', DELIV: 'deliver ho gaya hai', PEND: 'pending hai',
  CANC: 'cancel ho gaya hai', RTN: 'return ho gaya hai',
};
const friendly = s => {
  const t = String(s || '').toUpperCase();
  const hit = Object.keys(statusMap).find(k => t.startsWith(k));
  return hit ? statusMap[hit] : (t || 'unknown');
};
const ordersText = orders.length
  ? orders.map(o => '- ' + String(o.order_id || '') + ' | ' + String(o.product || o.items_summary || '-') + ' | Qty: ' + String(o.quantity || '-') + ' | Rs ' + String(o.total_amount || '-') + ' | Status: ' + friendly(o.status)).join('\n')
  : '';

// ===== LIVE CATALOG (rates isi se quote honge) =====
const catalog = $('Load Routing Products').all()
  .map(i => i.json || {})
  .filter(p => p && p.name && p.active !== false)
  .map(p => '- ' + String(p.name) + ' | ' + String(p.category || '') + ' | ' + String(p.unit || '') + ' | Rs ' + String(p.price || ''))
  .join('\n');

// ===== MID-ORDER FLOW STATE =====
const flowText = (state !== 'idle' && state !== 'ai_chat')
  ? ('ORDER FLOW STATE: ' + state +
    (sessCtx.product ? ' | Product: ' + sessCtx.product : '') +
    (sessCtx.quantity ? ' | Quantity: ' + sessCtx.quantity : '') +
    (sessCtx.address ? ' | Address: ' + sessCtx.address : ''))
  : '';

// ===== HISTORY (follow-ups ke liye) =====
const hist = Array.isArray(sessCtx.history) ? sessCtx.history.slice(-3) : [];
const histText = hist.map(h => 'Customer: ' + String(h.q || '').slice(0, 150) + '\nBarkat: ' + String(h.a || '').slice(0, 200)).join('\n');

const userMsg =
  (histText ? 'Pichli guftagu (sirf reference ke liye):\n' + histText + '\n\n' : '') +
  (ordersText ? 'CUSTOMER ORDERS (verified data):\n' + ordersText + '\n\n' : '') +
  (catalog ? 'CATALOG (rates sirf isi se):\n' + catalog + '\n\n' : '') +
  (flowText ? flowText + '\n\n' : '') +
  'Ab ka naya sawal: ' + q;

const sys = `Tum "Barkat" ho — AllBarka (luxury dry fruits, nuts, herbs aur spices ka Pakistani brand) ka WhatsApp AI assistant. Tum trained CUSTOMER CARE SPECIALIST aur SALES AGENT dono ka kaam karte ho. Zuban: Roman Urdu. Lehja: meharban, professional, chhota aur seedha.

