// ===== Extract AI Reply V5 (Groq Llama 3.3 + delivery/custom pricing validation + neutral persona) =====
const ctx = $('Prepare Conversation Context').first().json || {};
const question = String(ctx.text || '');
const humanLink = 'https://wa.me/923160666083';
const disclaimer = '⚕️ Behtar mashwarah ke liye apne doctor ya nutritionist se zaroor rabta karein.';
const allergyLine = '⚠️ Agar nuts allergy hai to nuts se parhez karein.';

// Groq response shape: choices[0].message.content
const choice = Array.isArray($json.choices) ? $json.choices[0] : null;
const raw = choice && choice.message && choice.message.content
  ? String(choice.message.content).trim()
  : '';

if ($json.error || !raw) {
  return [{ json: { ...ctx, to: ctx.from, replyType: 'ai_offline',
    replyText: 'Filhaal AI assistant available nahi hai. Thori dair baad koshish karein ya human support se baat karein: ' + humanLink + '\nMenu ke liye *Menu* likhein.' } }];
}

let decision = {};
try { decision = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { try { decision = JSON.parse(m[0]); } catch (e2) {} }
}

const action = String(decision.action || '').toLowerCase();
let reply = String(decision.reply || '').replace(/\\n/g, '\n').trim();

// Hindi shabd → Roman Urdu cleanup
reply = reply
  .replace(/swasthya|swasthiya/gi, 'sehat')
  .replace(/dhanyavaad/gi, 'shukriya')
  .replace(/kripya/gi, 'meherbani');

// SECURITY: sirf official link allow — baqi URLs strip (phishing guard)
reply = reply
  .replace(/https?:\/\/[^\s]+/gi, url => url.startsWith(humanLink) ? url : '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (action === 'human') {
  if (!reply) reply = 'Hamari team aapse jald rabta karegi — foran baat ke liye:';
  if (!reply.includes('wa.me/')) reply += '\n' + humanLink;
} else if (!reply) {
  reply = 'Maaf kijiye, sawal samajh nahi aaya. *Menu* likhein ya apna sawal dobara likhein.';
} else {
  // ===== PRICE VALIDATION V4 =====
  // Allowed: catalog rates + customer order totals + delivery prices (150/250/3000)
  //          + per-kg delivery multiples (250, 500, 750...) + custom per-gram calculations
  try {
    const allowed = new Set([150, 250, 3000]);
    for (const it of $('Load Routing Products').all()) {
      const p = Number(it.json && it.json.price);
      if (Number.isFinite(p) && p > 0) allowed.add(p);
    }
    for (const it of $('Load AI Orders').all()) {
      const t = Number(it.json && it.json.total_amount);
      if (Number.isFinite(t) && t > 0) allowed.add(t);
    }

    // Per-gram rates catalog units se (jaise "250g" → price/250)
    const perGramRates = [];
    for (const it of $('Load Routing Products').all()) {
      const p = it.json || {};
      const price = Number(p.price);
      const um = String(p.unit || '').toLowerCase().replace(/\s+/g, '').match(/(\d+(?:\.\d+)?)(kg|kgs|g|gm|gram|grams)?/);
      if (Number.isFinite(price) && price > 0 && um) {
        const grams = Number(um[1]) * (um[2] && um[2].startsWith('k') ? 1000 : 1);
        if (grams > 0) perGramRates.push({ name: String(p.name || ''), perGram: price / grams });
      }
    }

    const priceOk = (price, line) => {
      if (allowed.has(price)) return true;
      // Delivery per-kg multiples: 2kg=500, 3kg=750...
      if (/(delivery|shipping|charges|kg|kilo)/i.test(line) && price >= 250 && price <= 10000 && price % 250 === 0) return true;
      // Custom quantity per-gram calculation (line mein weight ho, jaise "700g ... Rs 1260")
      const wm = line.match(/(\d+(?:\.\d+)?)\s*(kg|kgs|g|gm|gram|grams)\b/i);
      if (wm) {
        const w = Number(wm[1]) * (/^k/i.test(wm[2]) ? 1000 : 1);
        if (w > 0) {
          for (const r of perGramRates) {
            const expected = r.perGram * w;
            if (Math.abs(price - expected) <= Math.max(3, expected * 0.03)) return true;
          }
        }
      }
      return false;
    };

    const lines = reply.split('\n');
    const kept = lines.filter(line => {
      const prices = Array.from(line.matchAll(/rs\.?\s*([\d,]+)/gi)).map(m => Number(m[1].replace(/,/g, '')));
      if (!prices.length) return true;
      return prices.every(p => priceOk(p, line));
    });
    if (kept.length < lines.length) {
      const joined = kept.join('\n').trim();
      reply = joined.length > 20
        ? joined + '\n\n(Sahi rate ke liye Menu se Catalogue kholein.)'
        : 'Rate Menu ke Catalogue mein hain. Product ka naam likhein — foran bata diya jayega.';
    }
  } catch (e) {}

  // Health disclaimer safety net
  const healthRe = /(fayda|fayde|faida|faide|sehat|health|nutrition|protein|vitamin|calorie|bimari|diabetes|sugar|cholesterol|blood|bp\b|dawa|ilaj|treatment|benefit|dard)/i;
  if (healthRe.test(question + ' ' + reply) && !reply.includes('doctor')) reply += '\n\n' + disclaimer;

  // Allergy safety net
  const allergyRe = /(allerg|aleji|nuts)/i;
  if (allergyRe.test(question + ' ' + reply) && !reply.includes('parhez')) reply += '\n\n' + allergyLine;
}

return [{ json: { ...ctx, to: ctx.from, replyType: 'ai_reply', replyText: reply.slice(0, 3800) } }];

